templates.rules:
location / { try_files $uri /index.php?$query_string; }
location @rewrite { rewrite ^ /index.php; }
location ~ ^/sites/[^/]+/files/styles/ { try_files $uri @rewrite; }
location ~ ^/sites/[^/]+/files/.*\.php$ { deny all; }
location ~* \.(engine|inc|install|make|module|profile|po|sh|sql|theme|twig|xtmpl|yml)(~|\.sw[op]|\.bak|\.orig|\.save)?$ { deny all; return 404; }
location ~ /vendor/.*\.php$ { deny all; return 404; }

location / { try_files $uri $uri/ @opencart; }
location @opencart { rewrite ^/(.+)$ /index.php?_route_=$1 last; }
location ~* ^/(system|vendor|catalog/controller|catalog/model|admin/controller|admin/model)/.*\.(php|tpl|twig)$ { deny all; }

location / { try_files $uri $uri/ @mediawiki; }
location @mediawiki { rewrite ^/(.*)$ /index.php?title=$1&$args last; }
location ~* ^/images/.*\.(php|phtml|php5|php7)$ { deny all; }
location ~* ^/(cache|includes|maintenance|serialized|tests|languages|vendor)/ { deny all; }
location = /LocalSettings.php { deny all; }

location / { try_files $uri $uri/ @rewrite; }
location @rewrite { rewrite ^/(.*)$ /app.php/$1 last; }
location ~ ^/app\.php(/|$) {
    include fastcgi_params;
    fastcgi_split_path_info ^(.+\.php)(/.*)$;
    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
    fastcgi_param PATH_INFO $fastcgi_path_info;
    fastcgi_param HTTPS $https if_not_empty;
    fastcgi_pass unix:%SOCK%;
    fastcgi_read_timeout 300;
}
location ~ ^/(config\.php|common\.php|cache|files|images/avatars/upload|includes|store|vendor)(/|$) { deny all; }

location / { try_files $uri $uri/ @modx-rewrite; }
location @modx-rewrite { rewrite ^/(.*)$ /index.php?q=$1&$args last; }
location ~* ^/(core|setup)/ { deny all; }
